use tokio::select;
use tokio::time::{sleep, Duration};

#[tokio::main]
async fn main() {
    let result = select! {
        _ = sleep(Duration::from_millis(100)) => "Timeout 1 won",
        _ = sleep(Duration::from_millis(50)) => "Timeout 2 won",
    };

    println!("{}", result);
}

use tokio::time::{sleep, Duration};

async fn task(name: &'static str, ms: u64) -> &'static str {
    sleep(Duration::from_millis(ms)).await;
    name
}

#[tokio::main]
async fn main() {
    let (x, y) = tokio::join!(task("fast", 10), task("slow", 20));
    println!("{} {}", x, y);
}

